update public.poetry as p
set body = x.body
from (
  select x->>'slug' as slug, x->>'body' as body
  from jsonb_array_elements($bodies$[{"slug":"tum-p056","body":"اے میری زیست  میرے جہاں کے سیریوس\nتو کہاں کھو گیا ہے جو اب نظر میں نہیں آتا\nتجھے تلاشے ہیں میری دھندلاتی نگاہیں\nکس جہاں کا ہوا ہے جو دہر میں نہیں آتا\n\nیہ سنورتی ہوئی دنیا یہ اجرتے ہوئے میرے ارماں\nیہ خواب میرے نیندوں سے بھی بچھڑنے لگے ہیں\nکبھی تو یوں لگتا ہے کہ اب کچھ نہیں آس\nقندیل میری ہستی کے بجھنے لگے ہیں\n\nکیوں یہ دل پتھر سا بھی موم ہوا ہے\nکیوں آنکھوں سے چشمے اگلنے لگے ہیں\nکیوں اک دم سے بدلا ہے موسم نے انداز\nکیوں ابر جیسے ہم پہ ہی گرجنے لگے ہیں\n\nکیوں تم کو کھویا ہے کیوں یہ درد ملا بھی\nیہ مقدر میں لکھا تھا کیا ہی رب سے گلہ بھی\nبس یہ التجا ہے اب کہ تم مطمئن رہو\nتمہیں درگزر ملے اور اچھے کا سلہ بھی"},{"slug":"tum-p057","body":"میں نے تیری آنکھوں میں بچھڑنے کی خوشی دیکھی\nایک اجڑا ہوا مسکن دیکھا ، ایک نئی سی زندگی دیکھی\n\nکچھ خواب ادھورے دیکھے ، کچھ شمعیں جلی دیکھیں\nایک راستہ مزین دیکھا ، ایک منزل نئی دیکھی\n\nکبھی اوڑھے ہوئے ملالوں کو سر پہ سجا دیکھا\nکبھی اٹھتے ہوئے سوالوں سے بھی کجی دیکھی\n\nکبھی ستاروں کی بھیڑ میں تنہائی کا احساس ملا\nکبھی ایک چاند کی چاندنی میں دل جوئی دیکھی\n\nدل میں تو بےبسی کے خزاں رسیدہ شجر دیکھے\nچہرے پہ چھلکتی ہوئی ایک ٹہنی ہری دیکھی\n\nہوئے ہیں راز راز ہم خوار جس ساگر کی وسعتوں میں\nاسی کے ساحل سے لگی ہوئی ایک ناو ٹوٹی دیکھی\n\nجن راہوں میں بچھتے ہیں محبتوں کے خوابیدہ چراغ\nانھی راہوں میں بل کھاتی ہوئی بےراہروی دیکھی\n\nاحمد ؔ  ہمیں پھر کہیں کسی کونے میں پڑے ہم ملے\nاور پھر ہم نے ہر طرف حدِ نگاہ روشنی دیکھی"},{"slug":"tum-p058","body":"خواب بے تعبیر، دل بےمایہ کی تشفی کے لیے\nزندگیاں گزاری گئیں ہیں بس اسی کے لیے\n\nہم بجھے بجھے سے بند کیواڑوں کے مکیں\nہم بھی کبھی تو نکلے تھے روشنی کے لیے\n\nاب کب تلک کرنا ہے اے خدا روشنی کا انتظار\nہم نئے شہر میں آئے تھے نئی زندگی کے لیے\n\nیہ رنجشیں ،یہ خلوتیں ،یہ تلخیاں فقط ہمارے لیے\nیہ مسرتیں ،یہ مروتیں، یہ عرضیاں سب کسی کے لیے\n\nسوچا کہ کریں اس بار بھی اسی ستمگر پہ اعتبار\nاف کہ پھر یہ آس جگی ہے اک اجنبی کے لیے\n\nگھڑی بھر کو تم سے ملنا تھا احمد ؔ\nعمر بھر انتظار کیا اس گھڑی کے لیے"},{"slug":"tum-p059","body":"دل ہے کہ تمناؤں کا زندان ہے کیا\nہر شخص ہی یہاں انجان ہے کیا\n\nجس کا حال ہم نے بار بار پوچھا\nوہ ہم ہی سے پریشان ہے کیا\n\nہم جہاں چاہ کربھی پہنچ نہ سکے\nوہ منزل بہت آسان ہے کیا\n\nریت بھری جلتی زندگی میں\nاہک شخص گلستان ہے کیا\n\nشوق ، تمنا ، بےبسی اور امید\nسب کا یہی امتحان ہے کیا\n\nکوئی وصل کا شعر نہیں احمد ؔ\nیہ بھی کوئی دیوان ہے کیا"},{"slug":"tum-p060","body":"افسوس زمانے کو غربت و افلاس کے غم ہیں\nصدشکر ہمیں بس تیرے اخلاص کے غم ہیں\n\nکیا ہوا جو دل بجھ گیا آس مر چکی ہے\nلوگوں کے تو میتِ خاص کے غم ہیں\n\nاے دل شب فراق تو رویا بھی نہ تھا\nتجھ کو کہاں سے حساس کے غم ہیں\n\nغم زمانے میں تلخیوں کے کم ہیں\nہر سو یہاں پہ مٹھاس کے غم ہیں\n\nاحمد ؔ اور زندگی بہت ٹھیک ٹھاک سی ہے\nبس کہنے کو اک دل اداس کے غم ہیں"}]$bodies$::jsonb) x
) as x
where p.slug = x.slug;
